/**
 * The IMD radars beyond the ones measured by hand in radar.model.ts, as their pictures were on 23 Oct 2026 (the radar-pictures workflow keeps a
 * copy on the imd-radar-samples branch): for each product the map square in the picture (crop), the range it spans from the radar to each
 * side, and the legend's colours with the reflectivity each stands for (rain rates and totals already turned into dBZ, Z = 200 R^1.6).
 *
 * How they were read: the map square from the picture's own frame (its panels, range rings or axes); the range printed on the picture
 * ("Max Range", "Range", "Display Range"); the legend by sampling its colour bar or swatches, each colour given the value its labels put
 * there (a gradient bar every few pixels, a box at its middle). Places from IMD's station map, or printed on the picture (printedSite).
 * A product whose picture could not be measured (the radar down, or no range printed) is marked unmeasured: it is never fetched.
 *
 * Palette entries: [r, g, b, dBZ] or [r, g, b, dBZ, tolerance] or [r, g, b, dBZ, tolerance, 1] where 1 marks a colour the map also uses
 * (white, cream, pale blue: an echo only next to other echoes). 'chennai': the Selex Rainbow legend of Chennai's picture.
 */
import type { RadarBand, RadarCropConfig, RadarProductKey } from './radar.model';

export type MeasuredColour = [number, number, number, number] | [number, number, number, number, number] | [number, number, number, number, number, 1];

export type MeasuredProduct = { rangeKm: number; crop: RadarCropConfig; palette?: MeasuredColour[] | 'chennai' } | { unmeasured: true };

export interface MeasuredStation {
  id: string;
  name: string;
  code: string;
  state: string;
  lat: number;
  lng: number;
  band: RadarBand;
  /** The place is the one printed on the radar's own picture (else IMD's station map, a few km at most from the radar). */
  printedSite?: boolean;
  products: Record<RadarProductKey, MeasuredProduct>;
}

